// GoDaddy on the business's own credentials: every operation of GoDaddy's public API (domains v1/v2/v3 and DNS,
// forwarding, transfers, notifications; SSL certificates; account, orders and subscriptions; hosting apps; email
// mailboxes; Commerce stores, customers, catalog, orders and taxes; shopping checkout; auctions, aftermarket,
// parking, domain value, abuse tickets, Agent Name Service).
// actions.json is generated by `bun scripts/openapi-actions.ts godaddy`; COVERAGE.md says what's left out.
//
// GoDaddy has two kinds of login and some APIs take only one: a Personal Access Token (Bearer; Domains v3, Hosting,
// Email, Shopping, Commerce, ANS) and the classic key:secret (sso-key; Auctions, Certificates, Abuse, Orders,
// Subscriptions…). Domains v1/v2 take either. People paste one or both, separated by a space; each call uses the one
// its API wants and falls back to the other.
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, type Send } from "../openapi";

const BASE = "https://api.godaddy.com";

export function credentials(key: string) {
  const parts = key.trim().split(/\s+/).filter(Boolean);
  return { pat: parts.find((p) => !p.includes(":")), sso: parts.find((p) => p.includes(":")) };
}

// APIs that take the classic key (or only it): it goes first when both were given
const SSO_FIRST =
  /^\/v[12]\/(certificates|abuse|agreements|countries|orders|subscriptions|aftermarket)|^\/v2\/customers\/[^/]+\/certificates?\/|\/(aftermarket|auctions|parking)\/|\/paymentProfiles/;

// how one call to `send` goes out with this login
export function apiFor(send: Pick<Send, "method" | "path" | "base">, key: string): Api {
  const { pat, sso } = credentials(key);
  const classic = Boolean(sso && (!pat || SSO_FIRST.test(send.path)));
  // a token refused by an API that wants the classic key says nothing about the token
  const wrongKind = !classic && SSO_FIRST.test(send.path);
  return {
    name: "GoDaddy",
    base: BASE,
    tokenHelp: "developer.godaddy.com/personal-access-token, or a classic key at classic-developer.godaddy.com/keys",
    auth: () => {
      const headers: Record<string, string> = { Authorization: classic ? `sso-key ${sso}` : `Bearer ${pat}`, Accept: "application/json" };
      // Hosting's partial updates are JSON Patch
      if (send.method === "PATCH" && send.base?.endsWith("/v1/hosting")) headers["Content-Type"] = "application/json-patch+json";
      // Orders and Subscriptions want an app key for their tracking
      if (/^\/v1\/(orders|subscriptions)/.test(send.path)) headers["X-App-Key"] = "emplio";
      return headers;
    },
    deadToken: (status) => status === 401 && !wrongKind,
    // Commerce's GraphQL answers a 200 with only errors
    failed: (body) => (Array.isArray(body?.errors) && body.errors.length && !body.data ? body.errors.map((e: any) => e.message).join("; ") : undefined),
  };
}

async function send(s: Send, key: string, input: Record<string, unknown>) {
  try {
    return await call(apiFor(s, key), key, s, input);
  } catch (e) {
    if (e instanceof AppsError && !e.expired && / \((401|403)\)$/.test(e.message) && SSO_FIRST.test(s.path) && !credentials(key).sso)
      throw new AppsError(`${e.message}. This part of GoDaddy takes a classic key: add KEY:SECRET (classic-developer.godaddy.com/keys) to the GoDaddy connection`);
    throw e;
  }
}

// a domain's transfer code comes with its details; it's handed out only by get_domain_auth_code, which asks first
const HIDE_AUTH_CODE = new Set(["v1_list_domains", "v1_get_domain", "v2_get_domain"]);
const hideAuthCode = (out: any): any =>
  Array.isArray(out) ? out.map(hideAuthCode) : out && typeof out === "object" && "authCode" in out ? { ...out, authCode: "(hidden: use get_domain_auth_code)" } : out;

type Generated = { name: string; description: string; readOnly: boolean; input: object; send: Send };
const generated = (await Bun.file(new URL("./actions.json", import.meta.url)).json()) as { actions: Generated[] };

const actions: Record<string, OwnAction> = Object.fromEntries(
  generated.actions.map((a) => [
      a.name,
      {
        description: a.description,
        readOnly: a.readOnly,
        input: z.fromJSONSchema(a.input as z.core.JSONSchema.JSONSchema) as z.ZodObject,
        run: async (input: Record<string, unknown>, key: string) => {
          // the ids GoDaddy uses to de-duplicate and trace: a fresh one per call unless given
          const i = { ...input };
          for (const [field, header] of a.send.headers) if (/^(idempotency-key|request-id|x-request-id)$/i.test(header) && i[field] === undefined) i[field] = crypto.randomUUID();
          const out = await send(a.send, key, i);
          return HIDE_AUTH_CODE.has(a.name) ? hideAuthCode(out) : out;
        },
      },
    ]),
);

actions.get_domain_auth_code = {
  description:
    "Get a domain's transfer authorization (EPP) code, to move the domain to another registrar. Shows a secret: only when the person needs it, never pasted in a chat.",
  input: z.object({ domain: z.string().describe("The domain, e.g. example.com") }),
  run: async ({ domain }: { domain: string }, key: string) => {
    const out = (await send({ method: "GET", path: "/v1/domains/{domain}", query: [], headers: [] }, key, { domain })) as { authCode?: string };
    if (!out.authCode) throw new AppsError("GoDaddy gave no transfer code for this domain (it may be locked or not transferable yet)");
    return { domain, authCode: out.authCode };
  },
};

export const godaddy: OwnApp = {
  app: "godaddy",
  name: "GoDaddy",
  logo: "/logos/godaddy.svg",
  keyField: {
    label: "Personal access token (and/or key:secret)",
    help:
      "developer.godaddy.com/personal-access-token → Generate Token: tick Domains & DNS plus anything else Emplio should run (Hosting, Email, Commerce), and pick the longest expiry. " +
      "Certificates, auctions, orders and subscriptions still need a classic production key (classic-developer.godaddy.com/keys, not OTE): paste it as KEY:SECRET, after the token with a space if you have both.",
    placeholder: "gd_pat_xxxxxxxx  KEY:SECRET",
  },
  // whose account it is; a 403 means a working login without the shopper scope, which is fine
  async check(key) {
    const { pat, sso } = credentials(key);
    if (!pat && !sso) throw new AppsError("Paste a GoDaddy personal access token, or a classic key as KEY:SECRET");
    try {
      const me = (await send({ method: "GET", path: "/v1/shoppers/{shopperId}", query: [], headers: [] }, key, { shopperId: "MY" })) as { nameFirst?: string; nameLast?: string; email?: string; shopperId?: string };
      return [me.nameFirst, me.nameLast].filter(Boolean).join(" ") || me.email || me.shopperId;
    } catch (e) {
      if (e instanceof AppsError && e.expired) throw e;
    }
  },
  actions,
};
